from __future__ import annotations

import hashlib
import json
import subprocess
import urllib.error
import urllib.request
from pathlib import Path

home = Path.home()
runtime = home / ".local/share/prediction-project-executor/control-center"
source_root = Path.cwd() / "control/control_center"

def sha(path):
    try:
        return hashlib.sha256(path.read_bytes()).hexdigest()
    except Exception:
        return None

def run(args):
    try:
        cp = subprocess.run(args, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=12)
        return {"rc": cp.returncode, "out": (cp.stdout or "")}
    except Exception as exc:
        return {"rc": -1, "out": f"{exc.__class__.__name__}:{exc}"}

def http_json(url):
    try:
        with urllib.request.urlopen(url, timeout=8) as response:
            body = response.read().decode("utf-8", errors="replace")
            return {"ok": True, "status": response.status, "body": json.loads(body)}
    except Exception as exc:
        return {"ok": False, "error": f"{exc.__class__.__name__}:{exc}"}

installed = {
    "server_matches": sha(runtime / "server.py") == sha(source_root / "server.py"),
    "ui_matches": sha(runtime / "static/index.html") == sha(source_root / "static/index.html"),
    "canary_matches": sha(runtime / "runtime_canary.py") == sha(source_root / "runtime_canary.py"),
}
service = run(["systemctl", "--user", "is-active", "prediction-control-center.service"])
health = http_json("http://127.0.0.1:8770/api/health")
snapshot = http_json("http://127.0.0.1:8770/api/snapshot")
journal = run(["journalctl", "--user", "-u", "prediction-control-center.service", "-n", "100", "--no-pager"])
lines = [line.strip() for line in journal["out"].splitlines() if line.strip()]
interesting = [
    line for line in lines
    if any(token in line for token in ("Traceback", "Error", "Exception", "Permission", "File ", "git", "CONTROL_CENTER"))
]
tail = (interesting[-12:] or lines[-12:])
diag = {
    "installed": installed,
    "service_rc": service["rc"],
    "service": service["out"].strip(),
    "health_ok": health.get("ok"),
    "health_status": health.get("status"),
    "health_error": health.get("error"),
    "snapshot_ok": snapshot.get("ok"),
    "snapshot_error": snapshot.get("error"),
    "snapshot_schema": (snapshot.get("body") or {}).get("schema") if snapshot.get("ok") else None,
    "git_sync": ((snapshot.get("body") or {}).get("git_sync") or {}).get("status") if snapshot.get("ok") else None,
    "active_tasks": ((snapshot.get("body") or {}).get("counts") or {}).get("tasks") if snapshot.get("ok") else None,
    "chain_alerts": len((snapshot.get("body") or {}).get("chain_alerts") or []) if snapshot.get("ok") else None,
    "journal": " || ".join(tail)[-2200:],
}
print("CONTROL_CENTER_E011_RUNTIME_DIAG=" + json.dumps(diag, separators=(",", ":")), flush=True)
raise SystemExit(17)
